const features = [
  {
    title: "Practical Learning",
    description:
      "No boring slides. Build real-world applications that populate your portfolio and impress recruiters.",
    icon: <PracticalLearningIcon />,
  },
  {
    title: "Mentorship",
    description:
      "Direct access to industry veterans who guide you through complex projects and career decisions.",
    icon: <MentorshipIcon />,
  },
  {
    title: "Community",
    description:
      "Join a network of thousands of learners and alumni helping each other climb the tech ladder.",
    icon: <CommunityIcon />,
  },
] as const;

export function WhyTechUp() {
  return (
    <Section className="bg-surface">
      <SectionHeading
        title="Why TechUp Academy?"
        subtitle="We bridge the gap between academic theory and industry requirements with a curriculum designed by experts."
      />
      <Stagger className="mt-8 grid gap-4 sm:mt-12 sm:gap-5 md:grid-cols-3">
        {features.map((feature) => (
          <article
            key={feature.title}
            data-reveal
            className="rounded-2xl border border-border bg-white p-5 sm:p-6"
          >
            <div className="h-14 w-14">{feature.icon}</div>
            <h3 className="mt-4 font-display text-lg font-bold text-navy sm:mt-5 sm:text-xl">
              {feature.title}
            </h3>
            <p className="mt-2 text-sm leading-relaxed text-muted-foreground">
              {feature.description}
            </p>
          </article>
        ))}
      </Stagger>
    </Section>
  );
}
